WITH eligible AS (SELECT s.* FROM departments s WHERE NOT EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND c.level NOT IN ('L4', 'L1'))), latest_match AS (SELECT s.*, latest.employee_level, latest.employee_job_title FROM eligible s LEFT JOIN LATERAL (SELECT c.level AS employee_level, c.job_title AS employee_job_title FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) latest ON TRUE), deduped AS (SELECT * FROM latest_match QUALIFY RANK() OVER (PARTITION BY employee_level ORDER BY budget) = 1), kept_keys AS (SELECT id, dept_name FROM deduped EXCEPT SELECT id, dept_name FROM departments WHERE location IN ('Singapore', 'New York')), kept_rows AS (SELECT s.* FROM deduped s JOIN kept_keys k ON s.id = k.id AND s.dept_name = k.dept_name), metrics AS (SELECT *, PERCENT_RANK() OVER (ORDER BY budget) AS budget_percent_rank, ROUND(budget / SUM(budget) OVER (PARTITION BY employee_job_title), 4) AS budget_share, ROUND(budget / SUM(budget) OVER (PARTITION BY employee_job_title), 4) AS budget_share_2, ROUND(budget / SUM(budget) OVER (PARTITION BY dept_name, location), 4) AS budget_share_3 FROM kept_rows), kept AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.hire_date <= '2025-10-01')), kept_departments AS (SELECT s.* FROM kept s WHERE EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND c.job_title NOT IN ('Engineer', 'Intern'))) SELECT id, dept_name, location, budget, employee_level, employee_job_title, budget_percent_rank, budget_share, budget_share_2, budget_share_3, RANK() OVER (ORDER BY budget DESC NULLS FIRST) AS budget_rank, PERCENT_RANK() OVER (ORDER BY budget_share DESC NULLS LAST) AS budget_share_percent_rank FROM kept_departments;
